def SignedSumsBounded (x : ℕ → E) (M : ℝ) : Prop :=
  ∀ (N : ℕ) (ε : ℕ → ℝ), (∀ n, ε n = 1 ∨ ε n = -1) →
    ‖∑ n ∈ Finset.range N, ε n • x n‖ ≤ M

